export const CreateTaskSessionResponse = zod
  .object({
    id: zod
      .uuid()
      .min(createTaskSessionResponseIdMin)
      .max(createTaskSessionResponseIdMax)
      .regex(createTaskSessionResponseIdRegExp)
      .describe("Unique session identifier."),
    task_id: zod
      .uuid()
      .min(createTaskSessionResponseTaskIdMin)
      .max(createTaskSessionResponseTaskIdMax)
      .regex(createTaskSessionResponseTaskIdRegExp)
      .describe("Task this session was recorded against."),
    identity: zod
      .object({
        harness: zod
          .string()
          .min(1)
          .max(createTaskSessionResponseIdentityHarnessMax)
          .regex(createTaskSessionResponseIdentityHarnessRegExp)
          .describe(
            "The agent harness or tool making the call (e.g. claude-code, cursor, custom-script).",
          ),
        agent_model: zod
          .string()
          .min(1)
          .max(createTaskSessionResponseIdentityAgentModelMax)
          .regex(createTaskSessionResponseIdentityAgentModelRegExp)
          .describe("The agent or model performing the work (e.g. opus-5, human)."),
        session_id: zod
          .string()
          .min(1)
          .max(createTaskSessionResponseIdentitySessionIdMax)
          .regex(createTaskSessionResponseIdentitySessionIdRegExp)
          .describe(
            "Caller-generated session identifier for correlating work across multiple API calls within a single work session.",
          ),
        label: zod
          .string()
          .min(1)
          .max(createTaskSessionResponseIdentityLabelMax)
          .regex(createTaskSessionResponseIdentityLabelRegExp)
          .optional()
          .describe(
            'Optional human-readable label for this session (e.g. "S3 domain core", "bug fix #42").',
          ),
      })
      .describe(
        "Self-declared caller descriptor. Not authentication — callers identify themselves on claim and report calls. The harness (e.g. Claude Code, Cursor), the agent/model (e.g. Opus 5), a session identifier, and an optional label. Stored on sessions and claims; humans get an identity too.",
      ),
    started_at: zod.iso
      .datetime({ offset: true })
      .min(createTaskSessionResponseStartedAtMin)
      .max(createTaskSessionResponseStartedAtMax)
      .describe("When the work session started."),
    ended_at: zod.iso
      .datetime({ offset: true })
      .min(createTaskSessionResponseEndedAtMin)
      .max(createTaskSessionResponseEndedAtMax)
      .describe("When the work session ended."),
    outcome: zod.enum(["succeeded", "failed"]).describe("Whether the session succeeded or failed."),
    failure_reason: zod
      .string()
      .min(1)
      .max(createTaskSessionResponseFailureReasonMax)
      .regex(createTaskSessionResponseFailureReasonRegExp)
      .nullish()
      .describe(
        "Explanation of why the session failed. Required when outcome is `failed`, null otherwise.",
      ),
    summary: zod
      .string()
      .min(createTaskSessionResponseSummaryMin)
      .max(createTaskSessionResponseSummaryMax)
      .regex(createTaskSessionResponseSummaryRegExp)
      .describe("Human-readable summary of what was accomplished."),
    decisions: zod
      .array(
        zod
          .string()
          .min(1)
          .max(createTaskSessionResponseDecisionsItemMax)
          .regex(createTaskSessionResponseDecisionsItemRegExp),
      )
      .min(createTaskSessionResponseDecisionsMin)
      .max(createTaskSessionResponseDecisionsMax)
      .describe("Key decisions made during this session."),
    knowledge_items: zod
      .array(
        zod
          .object({
            id: zod
              .uuid()
              .min(createTaskSessionResponseKnowledgeItemsItemIdMin)
              .max(createTaskSessionResponseKnowledgeItemsItemIdMax)
              .regex(createTaskSessionResponseKnowledgeItemsItemIdRegExp)
              .describe("Unique knowledge item identifier."),
            type: zod
              .enum(["link", "transcript", "decision", "note"])
              .describe(
                "Knowledge item type. `link` = issue/PR/commit/doc. `transcript` = session transcript. `decision` = a recorded decision. `note` = refined, reusable content.",
              ),
            title: zod
              .string()
              .min(1)
              .max(createTaskSessionResponseKnowledgeItemsItemTitleMax)
              .regex(createTaskSessionResponseKnowledgeItemsItemTitleRegExp)
              .describe("Short title for the knowledge item."),
            content: zod
              .string()
              .min(1)
              .max(createTaskSessionResponseKnowledgeItemsItemContentMax)
              .regex(createTaskSessionResponseKnowledgeItemsItemContentRegExp)
              .describe("The knowledge item content."),
            scope: zod
              .enum(["task", "session", "project"])
              .describe(
                "Where this knowledge item is attached. `project` = project-level knowledge (conventions, goals). `task` = produced by or attached to a task. `session` = produced during a specific session.",
              ),
            task_id: zod
              .uuid()
              .min(createTaskSessionResponseKnowledgeItemsItemTaskIdMin)
              .max(createTaskSessionResponseKnowledgeItemsItemTaskIdMax)
              .regex(createTaskSessionResponseKnowledgeItemsItemTaskIdRegExp)
              .nullish()
              .describe("Task this item is attached to, if scope is `task`."),
            session_id: zod
              .uuid()
              .min(createTaskSessionResponseKnowledgeItemsItemSessionIdMin)
              .max(createTaskSessionResponseKnowledgeItemsItemSessionIdMax)
              .regex(createTaskSessionResponseKnowledgeItemsItemSessionIdRegExp)
              .nullish()
              .describe("Session this item is attached to, if scope is `session`."),
            project_id: zod
              .uuid()
              .min(createTaskSessionResponseKnowledgeItemsItemProjectIdMin)
              .max(createTaskSessionResponseKnowledgeItemsItemProjectIdMax)
              .regex(createTaskSessionResponseKnowledgeItemsItemProjectIdRegExp)
              .describe("Parent project identifier."),
            created_at: zod.iso
              .datetime({ offset: true })
              .min(createTaskSessionResponseKnowledgeItemsItemCreatedAtMin)
              .max(createTaskSessionResponseKnowledgeItemsItemCreatedAtMax)
              .describe("When this knowledge item was created."),
          })
          .describe(
            "A typed, reusable piece of information attached to a task, session, or the project itself. Addressable project-wide regardless of which task produced it.",
          ),
      )
      .min(createTaskSessionResponseKnowledgeItemsMin)
      .max(createTaskSessionResponseKnowledgeItemsMax)
      .describe("Knowledge items produced during this session."),
    artifacts: zod
      .array(
        zod
          .url()
          .min(1)
          .max(createTaskSessionResponseArtifactsItemMax)
          .regex(createTaskSessionResponseArtifactsItemRegExp),
      )
      .min(createTaskSessionResponseArtifactsMin)
      .max(createTaskSessionResponseArtifactsMax)
      .describe(
        "Links to artifacts produced (commits, PRs, files). Artifacts are not a separate entity — they are knowledge items of type `link`.",
      ),
    created_at: zod.iso
      .datetime({ offset: true })
      .min(createTaskSessionResponseCreatedAtMin)
      .max(createTaskSessionResponseCreatedAtMax)
      .describe("When this session record was created."),
  })
  .describe(
    "A structured work episode on a task. Records identity, timestamps, outcome, decisions made, knowledge items produced, and artifacts.",
  );

